//! Raw FFI bindings to the whisper.cpp checkout in `whisper.cpp/` (whisper + parakeet).
//!
//! Generated by bindgen at build time; see `build.rs`. Safe wrappers live in the app crate.

#![allow(non_upper_case_globals)]
#![allow(non_camel_case_types)]
#![allow(non_snake_case)]
#![allow(dead_code)]
#![allow(clippy::all)]

include!(concat!(env!("OUT_DIR"), "/bindings.rs"));

/// whisper.cpp release this crate is built from (read from the pinned CMakeLists.txt).
pub const WHISPER_CPP_VERSION: &str = env!("FING_WHISPER_CPP_VERSION");
